// buckets sorted ascending by le; counts are CUMULATIVE (count of obs <= le)
function quantile(buckets, q) {
  const total = buckets[buckets.length - 1].count;
  const targetRank = q * total;
  let chosen = buckets[0].le;
  for (const b of buckets) {
    if (b.count < targetRank) {
      chosen = b.le;
    }
  }
  return chosen;
}

